#!/usr/bin/env python3
"""Check the course content.

    python tools/check.py                 # structure + run every reference solution
    python tools/check.py --course python # only one course
    python tools/check.py --examples      # also run every runnable code block (zh-CN, en, ru)
    python tools/check.py --no-run        # structure only (no compilers needed)

Checks that:
  * every lesson has zh-CN, en and ru Markdown (zh-TW is generated by tools/zh_tw.py);
  * every exercise marker has data in exercises.toml, in every language;
  * choice questions have the same number of options in every language and a valid answer;
  * every reference solution passes its own tests (when the compiler is installed);
  * --examples: every runnable example compiles and runs without an error.
Exit code 1 if anything is wrong.
"""
from __future__ import annotations

import argparse
import concurrent.futures as cf
import os
import re
import sys
from pathlib import Path

# Many programs run in parallel; keep numeric libraries (PyTorch, NumPy) from each
# spawning one thread per CPU and starving the others into timeouts.
for _var in ("OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS"):
    os.environ.setdefault(_var, "1")

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "app"))

from tutor import runners  # noqa: E402
from tutor.content import Library, split_lesson  # noqa: E402
from tutor.markdown import render  # noqa: E402

REQUIRED = ["zh-CN", "en", "ru"]


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--course")
    ap.add_argument("--lesson")
    ap.add_argument("--root", default=str(ROOT))
    ap.add_argument("--no-run", action="store_true")
    ap.add_argument("--examples", action="store_true")
    ap.add_argument("--jobs", type=int, default=4)
    args = ap.parse_args()
    lib = Library(args.root)
    chains = runners.Toolchains()
    problems: list[str] = []
    jobs = []
    skipped: set[str] = set()
    n_lessons = n_ex = 0
    for cid, course in lib.courses.items():
        if args.course and cid != args.course:
            continue
        for lid in course.lesson_ids:
            if args.lesson and lid != args.lesson:
                continue
            n_lessons += 1
            where = f"{cid}/{lid}"
            d = course.path / lid
            data = lib.exercise_data(cid, lid)
            ids_by_locale = {}
            for loc in REQUIRED + ["zh-TW"]:
                p = d / f"{loc}.md"
                if not p.exists():
                    if loc in REQUIRED:
                        problems.append(f"{where}: missing {loc}.md")
                    continue
                text = p.read_text(encoding="utf-8")
                if "\t" in text:
                    problems.append(f"{where}/{loc}.md: contains a tab character")
                title, body, segs = split_lesson(text)
                if not title:
                    problems.append(f"{where}/{loc}.md: no '# ' title")
                try:
                    render(body)
                except Exception as e:  # renderer must never crash
                    problems.append(f"{where}/{loc}.md: render error {e!r}")
                ids_by_locale[loc] = [i for i, _ in segs]
                lesson = lib.lesson(cid, lid, loc)
                for ex in lesson.exercises:
                    meta = data.get(ex.id)
                    if meta is None:
                        problems.append(f"{where}/{loc}.md: exercise '{ex.id}' has no entry in exercises.toml")
                        continue
                    if ex.kind == "choice":
                        if len(ex.options_md) < 2:
                            problems.append(f"{where}/{loc}.md: choice '{ex.id}' has {len(ex.options_md)} options")
                        if not isinstance(ex.answer, int) or not 0 <= ex.answer < len(ex.options_md):
                            problems.append(f"{where}/{loc}.md: choice '{ex.id}' answer out of range")
                    if ex.kind == "output" and not ex.code_md:
                        problems.append(f"{where}/{loc}.md: output exercise '{ex.id}' has no code block")
                    if ex.kind == "code" and loc in REQUIRED:
                        if not ex.tests:
                            problems.append(f"{where}: code exercise '{ex.id}' has no tests ({loc})")
                        elif not args.no_run:
                            jobs.append((f"{where}:{ex.id}:{loc}", ex.language, ex.solution, ex.tests, ex.match, ex.requires))
                        n_ex += 1
                if args.examples and loc in REQUIRED and not args.no_run:
                    for k, block in enumerate(render(body).code_blocks):
                        if block.runnable:
                            m = re.search(r'input="([^"]*)"', block.info)
                            stdin = m.group(1).replace("\\n", "\n").replace("\\t", "\t") + "\n" if m else None   # keeps non-ASCII text intact
                            req = re.search(r'requires=([\w,.-]+)', block.info)
                            limit = re.search(r'timeout=(\d+)', block.info)    # long demos (e.g. training a model)
                            jobs.append((f"{where}/{loc}.md block {k}", block.lang, block.code, stdin, "exact",
                                         req.group(1).split(",") if req else [],
                                         int(limit.group(1)) if limit else 20))
            base = ids_by_locale.get("zh-CN", [])
            for loc, ids in ids_by_locale.items():
                if ids != base:
                    problems.append(f"{where}: exercise ids differ between zh-CN {base} and {loc} {ids}")
            unused = set(data) - set(base)
            if unused:
                problems.append(f"{where}: exercises.toml has unused ids {sorted(unused)}")
            # choice option counts must agree
            for ex_id, meta in data.items():
                if meta.get("kind") == "choice":
                    counts = {loc: len(next((e.options_md for e in lib.lesson(cid, lid, loc).exercises if e.id == ex_id), []))
                              for loc in ids_by_locale}
                    if len(set(counts.values())) > 1:
                        problems.append(f"{where}: choice '{ex_id}' option counts differ {counts}")

    def run_job(job):
        name, lang, code, tests, match, requires, *extra = job
        example_timeout = extra[0] if extra else 20
        tool = chains.get(lang)
        if not tool.ok:
            return name, None, f"skipped ({lang} not installed)"
        for pkg in requires:
            if not chains.has_module(pkg):
                return name, None, f"skipped (python package {pkg} missing)"
        if tests is None or isinstance(tests, str):  # example block: must run without crashing
            stdin = tests if isinstance(tests, str) else "3\n4\n5\n" * 4
            report = runners.run_tests(chains, lang, code, [{"input": stdin, "output": ""}], "contains",
                                       timeout=example_timeout)
            r = report.results[0] if report.results else None
            if report.compile_failed:
                return name, False, "compile error:\n" + report.compile_output[-1500:]
            if r and (r.timeout or r.exit_code not in (0,)):
                return name, False, f"exit {r.exit_code} timeout={r.timeout}\n{r.stderr[-800:]}"
            return name, True, ""
        report = runners.run_tests(chains, lang, code, tests, match, timeout=30)
        if report.ok:
            return name, True, ""
        if report.compile_failed:
            return name, False, "compile error:\n" + report.compile_output[-1500:]
        bad = next(r for r in report.results if not r.passed)
        return name, False, (f"input={bad.input!r}\nexpected={bad.expected!r}\nactual={bad.actual!r}\n"
                             f"stderr={bad.stderr[-600:]}")

    ok_runs = 0
    with cf.ThreadPoolExecutor(max_workers=args.jobs) as pool:
        for name, ok, msg in pool.map(run_job, jobs):
            if ok is None:
                skipped.add(msg)
            elif ok:
                ok_runs += 1
            else:
                problems.append(f"{name}: FAILED\n    " + msg.replace("\n", "\n    "))
    print(f"lessons: {n_lessons}, code exercises: {n_ex}, runs passed: {ok_runs}/{len(jobs)}")
    for s in sorted(skipped):
        print("note:", s)
    for p in problems:
        print("✗", p)
    print("OK" if not problems else f"{len(problems)} problem(s)")
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())
